    pub async fn get_block(&self, height: u64) -> Result<Option<qnet_state::Block>, QNetError> {
        // v2.70: Use auto-format loader that handles both EfficientMicroBlock and legacy MicroBlock
        // EfficientMicroBlock stores only TX hashes - full TXs are in separate "transactions" CF
        // load_microblock_auto_format() reconstructs full block with transactions
        match self.storage.load_microblock_auto_format(height) {
            Ok(Some(microblock)) => {
                // Convert MicroBlock to Block format for API compatibility
                // v2.80: Include poh_hash and poh_count for VTS/PoH data in API response
                let block = qnet_state::Block {
                    height: microblock.height,
                    timestamp: microblock.timestamp,
                    previous_hash: microblock.previous_hash,
                    merkle_root: microblock.merkle_root,
                    transactions: microblock.transactions,
                    producer: microblock.producer.clone(),
                    signature: microblock.signature,
                    poh_hash: microblock.poh_hash,
                    poh_count: microblock.poh_count,
                    block_type: "MICROBLOCK".to_string(),
                };
                Ok(Some(block))
            }
            Ok(None) => Ok(None),
            Err(e) => Err(QNetError::StorageError(e.to_string())),
        }
    }
    
    pub async fn get_macroblock(&self, index: u64) -> Result<Option<qnet_state::MacroBlock>, QNetError> {
        // Get macroblock by index (not height!)
        // Macroblock #1 = blocks 1-90, #2 = blocks 91-180, etc.
        match self.storage.get_macroblock_by_height(index) {
            Ok(Some(data)) => {
                // Try to decompress first (macroblock might be compressed)
                let decompressed_data = match zstd::decode_all(&data[..]) {
                    Ok(decompressed) => decompressed,
                    Err(_) => data, // Not compressed, use as-is
                };
                
                // Deserialize MacroBlock
                match bincode::deserialize::<qnet_state::MacroBlock>(&decompressed_data) {
                    Ok(macroblock) => Ok(Some(macroblock)),
                    Err(e) => Err(QNetError::StorageError(format!("Failed to deserialize macroblock: {}", e))),
                }
            }
            Ok(None) => Ok(None),
            Err(e) => Err(QNetError::StorageError(e.to_string())),
        }
    }
    
    pub async fn submit_transaction(&self, tx: qnet_state::Transaction) -> Result<String, QNetError> {
        // PRODUCTION VALIDATION - reject invalid transactions immediately
        if let Err(validation_error) = tx.validate() {
            return Err(QNetError::ValidationError(format!("Transaction validation failed: {}", validation_error)));
        }
        
        // DECENTRALIZED: System transactions don't need signature
        // validated through deterministic consensus rules, not crypto signature
        // v2.53: Added PingCommitmentWithSampling to system transactions
        // v2.77: Added HeartbeatCommitment to system transactions
        let is_system_transaction = matches!(tx.tx_type, 
            qnet_state::TransactionType::RewardDistribution | 
            qnet_state::TransactionType::PingCommitmentWithSampling { .. } |
            qnet_state::TransactionType::HeartbeatCommitment { .. } |
            qnet_state::TransactionType::LightNodeEligibilityBitmap { .. }
        );
        
        if is_system_transaction {
            // System transactions are validated through consensus, not signatures
            if tx.from == "system_emission" {
                if is_info() { println!("[INFO][EMISSION] system_emission_tx_accepted (validated through consensus)"); }
            } else if tx.from == "system_ping_commitment" {
                // v2.53: Ping commitments are system transactions, validated by merkle proofs
                if is_info() { println!("[INFO][REWARDS] ping_commitment_accepted system_tx"); }
            } else if tx.from == "system_rewards_pool" && matches!(tx.tx_type, qnet_state::TransactionType::RewardDistribution) {
                // v2.70: Reward claims from system_rewards_pool
                // Signature was already verified by API endpoint on message "claim_rewards:{node_id}:{wallet}"
                // Here we just verify the TX has the required fields (signature, pubkey, data)
                if tx.signature.as_ref().map_or(true, |s| s.is_empty()) {
                    return Err(QNetError::ValidationError("Reward claim must have signature".to_string()));
                }
                if tx.public_key.as_ref().map_or(true, |k| k.is_empty()) {
                    return Err(QNetError::ValidationError("Reward claim requires public_key".to_string()));
                }
                // data contains "reward_claim:{node_id}:{amount}" - used for audit trail
                if tx.data.as_ref().map_or(true, |d| !d.starts_with("reward_claim:")) {
                    return Err(QNetError::ValidationError("Reward claim must have valid data field".to_string()));
                }
                let has_quantum = tx.dilithium_signature.as_ref().map_or(false, |s| !s.is_empty());
                if is_info() { 
                    println!("[INFO][REWARDS] claim_tx_accepted from=system_rewards_pool quantum_safe={}", has_quantum); 
                }
            } else if matches!(tx.tx_type, qnet_state::TransactionType::RewardDistribution) {
                // Other RewardDistribution TX (not from system_rewards_pool) - verify signature on TX hash
                if tx.signature.as_ref().map_or(true, |s| s.is_empty()) {
                    return Err(QNetError::ValidationError("Reward TX must be signed".to_string()));
                }
                if tx.public_key.as_ref().map_or(true, |k| k.is_empty()) {
                    return Err(QNetError::ValidationError("Reward TX requires public_key".to_string()));
                }
                
                if let Some(ref sig) = tx.signature {
                    if let Some(ref pubkey) = tx.public_key {
                        if !Self::verify_ed25519_tx_signature_async(&tx, sig, pubkey).await? {
                            return Err(QNetError::ValidationError(
                                "Invalid Ed25519 signature for reward TX".to_string()
                            ));
                        }
                    }
                }
                if is_info() { println!("[INFO][REWARDS] reward_tx_signature_verified"); }
            }
        } else {
            // Regular transactions MUST have signature
            if tx.signature.as_ref().map_or(true, |s| s.is_empty()) {
                return Err(QNetError::ValidationError("Transaction signature is empty".to_string()));
            }
            
            // v3.35: ALWAYS verify signature cryptographically — no shortcuts!
            // Previous v2.95.3 used "signature_verified":true in data field as shortcut,
            // which was a security anti-pattern (string match in user-accessible field).
            // Now that build_canonical_verify_message() ensures consistent formats
            // across RPC and gossip paths, we always verify.
            
            // CRITICAL SECURITY: Cryptographic signature verification
            // Step 1: Ed25519 signature (ALWAYS required)
            if let Some(ref sig) = tx.signature {
                if let Some(ref pubkey) = tx.public_key {
                    if !Self::verify_ed25519_tx_signature_async(&tx, sig, pubkey).await? {
                        return Err(QNetError::ValidationError(
                            "Invalid Ed25519 signature".to_string()
                        ));
                    }
                } else {
                    return Err(QNetError::ValidationError("public_key required".to_string()));
                }
            }
            
            // Step 2: Dilithium signature (OPTIONAL - quantum TX)
            if tx.dilithium_signature.is_some() {
                if !Self::verify_dilithium_tx_signature_async(&tx).await? {
                    return Err(QNetError::ValidationError(
                        "Invalid Dilithium signature".to_string()
                    ));
                }
                if is_info() {
                    println!("[INFO][SIGVERIFY] dilithium_verified tx={}", &tx.hash[..16.min(tx.hash.len())]);
                }
            }
        }
        
        if tx.amount == 0 && matches!(tx.tx_type, qnet_state::TransactionType::Transfer { .. }) {
            return Err(QNetError::ValidationError("Transfer amount cannot be zero".to_string()));
        }
        
        // SHARDING: Check if this is a cross-shard transaction
        if let Some(ref shard_coordinator) = self.shard_coordinator {
            if let qnet_state::TransactionType::Transfer { to, .. } = &tx.tx_type {
                let from_shard = shard_coordinator.get_shard(&tx.from);
                let to_shard = shard_coordinator.get_shard(to);
                
                if from_shard != to_shard {
                    // v3.11: Cross-shard transaction with Merkle proof support
                    if is_info() { 
                        println!("[INFO][SHARD] cross_shard_tx detected from={} to={}", 
                                 from_shard, to_shard); 
                    }
                    
                    // Create cross-shard transaction record
                    let cross_shard_tx = qnet_sharding::CrossShardTx {
                        tx_hash: tx.hash.clone(),
                        from_shard,
                        to_shard,
                        amount: tx.amount,
                        timestamp: std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_secs(),
                    };
                    
                    // Process through shard coordinator
                    if let Err(e) = shard_coordinator.process_cross_shard_tx(cross_shard_tx).await {
                        if is_warn() { println!("[WARN][SHARD] cross_shard_process_fail err={}", e); }
                        // Continue with normal processing even if cross-shard fails
                    } else if is_debug() {
                        println!("[DBG][SHARD] cross_shard_tx_queued hash={}...", &tx.hash[..16]);
                    }
                    
                    // v3.11: Note - Merkle proofs are generated when block is finalized
                    // Target shard can request proof via generate_cross_shard_proof()
                }
            }
        }
        
        // CRITICAL SECURITY: Check nonce BEFORE adding to mempool
        // This prevents DoS attacks where attacker floods mempool with invalid nonces
        // v2.93: System transactions bypass nonce check - use tx_type NOT from field!
        // HeartbeatCommitment has from=node_id, not "system_*"
        let is_system_tx = tx.from == "system_emission" 
            || tx.from == "system_ping_commitment"
            || tx.from.starts_with("system_")
            || matches!(tx.tx_type,
                qnet_state::TransactionType::HeartbeatCommitment { .. } |
                qnet_state::TransactionType::PingCommitmentWithSampling { .. } |
                qnet_state::TransactionType::LightNodeEligibilityBitmap { .. } |
                qnet_state::TransactionType::RewardDistribution |
                qnet_state::TransactionType::NodeRegistration { .. }
            );
        
        if !is_system_tx {
            let state = self.state.read().await;
            
            // Check nonce (only for user transactions)
            if let Some(account) = state.get_account(&tx.from) {
                let expected_nonce = account.nonce + 1;
                if tx.nonce != expected_nonce {
                    return Err(QNetError::ValidationError(format!(
                        "Invalid nonce: expected {}, got {} (anti-replay protection)",
                        expected_nonce, tx.nonce
                    )));
                }
            } else {
                // New account: nonce must be 1 (first transaction)
                if tx.nonce != 1 {
                    return Err(QNetError::ValidationError(format!(
                        "Invalid nonce for new account: expected 1, got {}",
                        tx.nonce
                    )));
                }
            }
            
            // Check balance (only for user transactions)
            let sender_balance = state.get_balance(&tx.from);
            
            // SECURITY: Use checked arithmetic to prevent overflow attacks
            // QUANTUM v2.25: Use effective_gas_price() for +50% Dilithium TX fee
            let effective_gas = tx.effective_gas_price();
            let gas_cost = effective_gas.checked_mul(tx.gas_limit)
                .ok_or_else(|| QNetError::ValidationError(
                    format!("Gas calculation overflow: {} * {}", effective_gas, tx.gas_limit)
                ))?;
            let required_balance = tx.amount.checked_add(gas_cost)
                .ok_or_else(|| QNetError::ValidationError(
                    format!("Balance calculation overflow: {} + {}", tx.amount, gas_cost)
                ))?;
            
            if sender_balance < required_balance {
                let quantum_note = if tx.is_quantum_signed() { " (includes +50% quantum fee)" } else { "" };
                return Err(QNetError::ValidationError(format!(
                    "Insufficient balance: have {}, need {}{}", 
                    sender_balance, required_balance, quantum_note
                )));
            }
        } else {
            // v2.65: System transactions bypass nonce AND balance checks
            if is_info() { println!("[INFO][TX] system_tx_bypass_validation from={}", tx.from); }
        }
        
        // PRODUCTION v2.77: Use BLAKE3 via calculate_hash() for consistency
        // CRITICAL: calculate_hash() excludes signature - no circular dependency!
        // This ensures TX hash is the same everywhere (mobile, explorer, blockchain)
        let tx_hash = tx.calculate_hash();
        
        // bincode still used for mempool storage (fast binary serialization)
        let tx_bytes = bincode::serialize(&tx)
            .map_err(|e| QNetError::SerializationError(format!("Failed to serialize transaction: {}", e)))?;
        
        // v2.26: Direct access - SimpleMempool is already thread-safe
        // No external lock needed - eliminates 100K TPS bottleneck!
        // v2.66: Log if not added, but DON'T return Err (duplicate is OK in P2P)
        let added = self.mempool.add_binary_transaction(tx_bytes.clone(), tx_hash.clone(), tx.gas_price);
        if !added {
            // This is NORMAL for P2P: same TX received from multiple peers
            // Only log for system TX (gas_price == u64::MAX) as those are important
            if tx.gas_price == u64::MAX {
                println!("[WARN][TX] system_tx_not_added hash={} (likely duplicate)", &tx_hash[..16.min(tx_hash.len())]);
            }
            // DON'T return Err! TX might already be in mempool from another peer
        }
        
        // Broadcast to network only after successful validation
        // PRODUCTION v2.25: bincode for network (10-20x faster than JSON)
        if let Some(unified_p2p) = &self.unified_p2p {
            let _ = unified_p2p.broadcast_transaction(tx_bytes);
        }
        
        // QUANTUM v2.25: Log effective gas (includes +50% for Dilithium)
        let effective_gas = tx.effective_gas_price() * tx.gas_limit;
        let quantum_flag = if tx.is_quantum_signed() { " 🔐QUANTUM" } else { "" };
        println!("[Transaction] ✅ Validated and submitted: {} (amount: {}, gas: {}{})", 
                 &tx_hash[..16.min(tx_hash.len())], tx.amount, effective_gas, quantum_flag);
        
        // v2.72: Broadcast PendingTx via WebSocket for real-time explorer updates
        if added {
            crate::rpc::broadcast_ws_event(crate::rpc::WsEvent::PendingTx {
                tx_hash: tx_hash.clone(),
                from: tx.from.clone(),
                to: tx.to.clone().unwrap_or_default(),
                amount: tx.amount,
            });
        }
        
        // v2.90: Return SHA3-256 hash (calculated via tx.calculate_hash())
        // ARCHITECTURE: TX must have hash set BEFORE calling submit_transaction()
        // because tx.validate() (line 16789) checks: self.hash == self.calculate_hash()
        Ok(tx_hash)
    }
    
    /// PRODUCTION v2.57: Verify Ed25519 on SIGVERIFY_RUNTIME
    /// ═══════════════════════════════════════════════════════════════════════════
    /// ISOLATION: Runs on dedicated SIGVERIFY_RUNTIME (not main event loop)
    /// PERFORMANCE: ~10,000 verifications/sec/core
    /// ═══════════════════════════════════════════════════════════════════════════
    async fn verify_ed25519_tx_signature_async(
        tx: &qnet_state::Transaction,
        signature_hex: &str,
        public_key_hex: &str
    ) -> Result<bool, QNetError> {
        let sig_hex = signature_hex.to_string();
        let pk_hex = public_key_hex.to_string();
        
        // CRITICAL FIX v3.31: Use type-aware canonical message
        let canonical_msg = Self::build_canonical_verify_message(tx);
        
        let handle = crate::unified_p2p::spawn_sigverify(async move {
            tokio::task::spawn_blocking(move || {
                use ed25519_dalek::{Signature, VerifyingKey, Verifier};
                
                let message = canonical_msg;
                let message_bytes = message.as_bytes();
                
                let sig_bytes = hex::decode(&sig_hex).map_err(|e| format!("Invalid sig hex: {}", e))?;
                if sig_bytes.len() != 64 { return Err(format!("Invalid sig len: {}", sig_bytes.len())); }
                let sig_array: [u8; 64] = sig_bytes.try_into().map_err(|_| "Sig conversion failed")?;
                let signature = Signature::from_bytes(&sig_array);
                
                let pk_bytes = hex::decode(&pk_hex).map_err(|e| format!("Invalid pk hex: {}", e))?;
                if pk_bytes.len() != 32 { return Err(format!("Invalid pk len: {}", pk_bytes.len())); }
                let pk_array: [u8; 32] = pk_bytes.try_into().map_err(|_| "PK conversion failed")?;
                let vk = VerifyingKey::from_bytes(&pk_array).map_err(|e| format!("Invalid pk: {}", e))?;
                
                match vk.verify(message_bytes, &signature) {
                    Ok(()) => Ok(true),
                    Err(_) => Ok(false),
                }
            }).await.map_err(|e| format!("Task panic: {}", e))?
        });
        
        match handle.await {
            Ok(Ok(r)) => Ok(r),
            Ok(Err(e)) => Err(QNetError::ValidationError(e)),
            Err(e) => Err(QNetError::ValidationError(format!("Runtime error: {}", e))),
        }
    }
    
    /// LEGACY sync wrapper
    #[allow(dead_code)]
    fn verify_ed25519_tx_signature(
        tx: &qnet_state::Transaction,
        signature_hex: &str,
        public_key_hex: &str
    ) -> Result<bool, QNetError> {
        use ed25519_dalek::{Signature, VerifyingKey, Verifier};
        
        // CRITICAL FIX v3.31: Use type-aware canonical message
        let message = Self::build_canonical_verify_message(tx);
        let message_bytes = message.as_bytes();
        
        let sig_bytes = hex::decode(signature_hex)
            .map_err(|e| QNetError::ValidationError(format!("Invalid signature hex: {}", e)))?;
        if sig_bytes.len() != 64 {
            return Err(QNetError::ValidationError(format!(
                "Invalid signature length: expected 64, got {}", sig_bytes.len()
            )));
        }
        let sig_array: [u8; 64] = sig_bytes.try_into()
            .map_err(|_| QNetError::ValidationError("Signature conversion failed".to_string()))?;
        let signature = Signature::from_bytes(&sig_array);
        
        let pk_bytes = hex::decode(public_key_hex)
            .map_err(|e| QNetError::ValidationError(format!("Invalid public_key hex: {}", e)))?;
        if pk_bytes.len() != 32 {
            return Err(QNetError::ValidationError(format!(
                "Invalid public_key length: expected 32, got {}", pk_bytes.len()
            )));
        }
        let pk_array: [u8; 32] = pk_bytes.try_into()
            .map_err(|_| QNetError::ValidationError("Public key conversion failed".to_string()))?;
        let verifying_key = VerifyingKey::from_bytes(&pk_array)
            .map_err(|e| QNetError::ValidationError(format!("Invalid public key: {}", e)))?;
        
        match verifying_key.verify(message_bytes, &signature) {
            Ok(()) => Ok(true),
            Err(_) => Ok(false),
        }
    }
    
    /// PRODUCTION v2.25.2: Batch verify Ed25519 signatures for high TPS
    /// Uses ed25519_dalek::verify_batch for 2-3x faster verification
    /// Returns indices of valid transactions
    pub fn verify_ed25519_batch(transactions: &[qnet_state::Transaction]) -> Vec<usize> {
        use ed25519_dalek::{Signature, VerifyingKey, Verifier};
        
        let mut valid_indices: Vec<usize> = Vec::with_capacity(transactions.len());
        
        // Prepare batch data
        let mut messages: Vec<Vec<u8>> = Vec::with_capacity(transactions.len());
        let mut signatures: Vec<Signature> = Vec::with_capacity(transactions.len());
        let mut verifying_keys: Vec<VerifyingKey> = Vec::with_capacity(transactions.len());
        let mut tx_indices: Vec<usize> = Vec::with_capacity(transactions.len());
        
        for (idx, tx) in transactions.iter().enumerate() {
            // SECURITY v6.1: Only truly unsigned system TXs skip batch Ed25519 check.
            // - RewardDistribution (system_emission): block-level only, never gossiped
            // - CreateAccount: internal system op, never gossiped individually
            // - BatchRewardClaims / BatchNodeActivations: DEPRECATED, never instantiated
            //
            // REMOVED from skip list (v6.1):
            // - NodeRegistration: client-signed NodeReg HAS Ed25519+Dilithium → verify early
            // - NodeActivation: now signed with ephemeral Ed25519 (v6.1) → verify early
            // - LightNodeEligibilityBitmap: now signed with ephemeral Ed25519 (v6.1) → verify early
            let is_unsigned_system_tx = matches!(tx.tx_type,
                qnet_state::TransactionType::RewardDistribution { .. } |
                qnet_state::TransactionType::CreateAccount { .. } |
                qnet_state::TransactionType::BatchRewardClaims { .. } |
                qnet_state::TransactionType::BatchNodeActivations { .. }
            );

            if is_unsigned_system_tx {
                // These TXs have no user Ed25519 — skip batch verify, evaluated later
                // RewardDistribution(claim) is verified in validate_and_add_network_transaction
                // system_emission RewardDistribution is REJECTED in validate_and_add (v6.1)
                valid_indices.push(idx);
                continue;
            }
            
            // Skip if no signature (non-system TX must have signature)
            let (sig_hex, pk_hex) = match (&tx.signature, &tx.public_key) {
                (Some(s), Some(p)) if !s.is_empty() && !p.is_empty() => (s, p),
                _ => continue,
            };
            
            // CRITICAL FIX v3.31: Use type-aware canonical message
            // See build_canonical_verify_message() for details on format mismatch
            let message = Self::build_canonical_verify_message(tx);
            
            // Decode signature
            let sig_bytes = match hex::decode(sig_hex) {
                Ok(b) if b.len() == 64 => b,
                _ => continue,
            };
            let sig_array: [u8; 64] = match sig_bytes.try_into() {
                Ok(a) => a,
                Err(_) => continue,
            };
            let signature = Signature::from_bytes(&sig_array);
            
            // Decode public key
            let pk_bytes = match hex::decode(pk_hex) {
                Ok(b) if b.len() == 32 => b,
                _ => continue,
            };
            let pk_array: [u8; 32] = match pk_bytes.try_into() {
                Ok(a) => a,
                Err(_) => continue,
            };
            let verifying_key = match VerifyingKey::from_bytes(&pk_array) {
                Ok(vk) => vk,
                Err(_) => continue,
            };
            
            messages.push(message.into_bytes());
            signatures.push(signature);
            verifying_keys.push(verifying_key);
            tx_indices.push(idx);
        }
        
        if messages.is_empty() {
            return valid_indices;
        }
        
        // BATCH VERIFY: 2-3x faster than individual verification
        // Try batch first, fallback to individual on failure
        let message_refs: Vec<&[u8]> = messages.iter().map(|m| m.as_slice()).collect();
        
        match ed25519_dalek::verify_batch(&message_refs, &signatures, &verifying_keys) {
            Ok(()) => {
                // All signatures valid
                if crate::node::is_info() {
                    println!("[INFO][ED25519] batch_ok count={}", tx_indices.len());
                }
                valid_indices.extend(tx_indices);
            }
            Err(e) => {
                // Batch failed - some signatures invalid, verify individually
                if crate::node::is_warn() {
                    println!("[WARN][ED25519] batch_failed count={} err={:?}", tx_indices.len(), e);
                }
                for (i, ((msg, sig), vk)) in messages.iter()
                    .zip(signatures.iter())
                    .zip(verifying_keys.iter())
                    .enumerate() 
                {
                    match vk.verify(msg, sig) {
                        Ok(()) => {
                        valid_indices.push(tx_indices[i]);
                        }
                        Err(e) => {
                            if crate::node::is_warn() {
                                println!("[WARN][ED25519] individual_fail idx={} msg_len={} err={:?}", 
                                    tx_indices[i], msg.len(), e);
                            }
                        }
                    }
                }
            }
        }
        
        valid_indices
    }
    
    /// PRODUCTION v2.57: Verify Dilithium3 on SIGVERIFY_RUNTIME
    /// ═══════════════════════════════════════════════════════════════════════════
    /// ISOLATION: Runs on dedicated SIGVERIFY_RUNTIME
    /// PERFORMANCE: ~1,000 verifications/sec/core (10x slower than Ed25519)
    /// SECURITY: CRYSTALS-Dilithium3 - NIST PQC Standard
    /// ═══════════════════════════════════════════════════════════════════════════
    /// CRITICAL FIX v3.31: Build canonical message matching the format used at signing time.
    /// User TXs (signed by mobile app) use "transfer:from:to:amount:nonce:gas_price:gas_limit".
    /// System TXs (signed by nodes) use "from|to|amount|nonce|gas_price|gas_limit|timestamp".
    /// Without this, Ed25519/Dilithium verification fails for gossiped user TXs.
    /// CRITICAL v3.31.1: Build canonical message for signature verification
    /// This MUST match EXACTLY how the client/RPC signed the message!
    /// 
    /// FORMAT MATRIX (source of truth):
    /// ┌─────────────────────┬──────────────────────────────────────────────────────────┬──────────────┐
    /// │ TX Type             │ Canonical Message Format                                 │ Signed By    │
    /// ├─────────────────────┼──────────────────────────────────────────────────────────┼──────────────┤
    /// │ Transfer            │ transfer:{from}:{to}:{amount}:{nonce}:{gas_price}:{gas}  │ User (mobile)│
    /// │ BatchTransfers      │ batch_transfer:{from}:{total}:{count}:{batch_id}         │ User (batch) │
    /// │ ContractDeploy      │ contract_deploy:{from}:{code_hash}:{nonce}               │ User (dApp)  │
    /// │ ContractCall        │ contract_call:{from}:{contract}:{method}:{nonce}          │ User (dApp)  │
    /// │ HeartbeatCommitment │ {from}|{to}|{amount}|{nonce}|{gas_price}|{gas}|{ts}      │ Node (hybrid)│
    /// │ PingCommitment      │ {from}|{to}|{amount}|{nonce}|{gas_price}|{gas}|{ts}      │ Node (hybrid)│
    /// │ RewardDistribution  │ claim_rewards:{node_id}:{wallet} (system_rewards_pool)   │ Client Ed25519│
    /// │ RewardDistribution  │ (SKIPPED in batch verify — emission/unsigned)             │ System       │
    /// │ NodeRegistration    │ (SKIPPED in batch verify — unsigned system TX)            │ System       │
    /// │ LightNodeBitmap     │ (SKIPPED in batch verify — unsigned system TX)            │ System       │
    /// └─────────────────────┴──────────────────────────────────────────────────────────┴──────────────┘
    fn build_canonical_verify_message(tx: &qnet_state::Transaction) -> String {
        let to_str = tx.to.as_ref().map(|s| s.as_str()).unwrap_or("");
        match &tx.tx_type {
            // === USER TRANSACTIONS (signed by mobile/dApp) ===
            
            // Transfer: matches WalletManager.js:5514 and rpc.rs:3923
            qnet_state::TransactionType::Transfer { .. } => {
                format!("transfer:{}:{}:{}:{}:{}:{}",
                    tx.from, to_str, tx.amount, tx.nonce, tx.gas_price, tx.gas_limit)
            }
            
            // BatchTransfers: matches rpc.rs:4645
            // CRITICAL FIX v3.31.1: 4th param is batch_id (NOT nonce!)
            // RPC signs: batch_transfer:{from}:{total_amount}:{count}:{batch_id}
            qnet_state::TransactionType::BatchTransfers { transfers, batch_id } => {
                let total_amount: u64 = transfers.iter().map(|t| t.amount).sum();
                format!("batch_transfer:{}:{}:{}:{}",
                    tx.from, total_amount, transfers.len(), batch_id)
            }
            
            // ContractDeploy: matches rpc.rs:10825
            // CRITICAL FIX v3.31.1: code_hash is stored in tx.data JSON, NOT sha3(data)!
            // RPC computes: sha3(base64_decode(wasm_code)) → hex → stores in data.code_hash
            // We extract code_hash from the JSON data field
            qnet_state::TransactionType::ContractDeploy => {
                let code_hash = if let Some(ref data) = tx.data {
                    // tx.data is a JSON string: {"code_hash":"abc...","code_size":...,"security":...}
                    // Extract code_hash field from JSON
                    serde_json::from_str::<serde_json::Value>(data)
                        .ok()
                        .and_then(|v| v.get("code_hash").and_then(|h| h.as_str().map(String::from)))
                        .unwrap_or_else(|| {
                            // Fallback: if data is not JSON (legacy), hash the raw data
                            use sha3::{Digest, Sha3_256};
                            let mut hasher = Sha3_256::new();
                            hasher.update(data.as_bytes());
                            format!("{:x}", hasher.finalize())
                        })
                } else {
                    String::new()
                };
                format!("contract_deploy:{}:{}:{}", tx.from, code_hash, tx.nonce)
            }
            
            // ContractCall: matches rpc.rs:11179
            // CRITICAL FIX v3.31.1: method is stored in tx.data JSON, NOT tx.data itself!
            // RPC signs: contract_call:{from}:{contract}:{method}:{nonce}
            // tx.data is JSON: {"contract":"...","method":"transfer","args":[...],"security":{...}}
            qnet_state::TransactionType::ContractCall => {
                let contract = to_str;
                let method = if let Some(ref data) = tx.data {
                    // tx.data is a JSON string — extract "method" field
                    serde_json::from_str::<serde_json::Value>(data)
                        .ok()
                        .and_then(|v| v.get("method").and_then(|m| m.as_str().map(String::from)))
                        .unwrap_or_default()
                } else {
                    String::new()
                };
                format!("contract_call:{}:{}:{}:{}", tx.from, contract, method, tx.nonce)
            }
            
            // === REWARD CLAIM (signed by client with Ed25519) ===
            // matches rpc.rs:7406 — client signs "claim_rewards:{node_id}:{wallet_address}"
            // node_id is extracted from tx.data: "reward_claim:{node_id}:{amount}:..."
            // CRITICAL FIX v3.42: Without this, gossip nodes reject claim TXs because
            // the default pipe-format doesn't match the signed message, causing ~6min delays
            qnet_state::TransactionType::RewardDistribution if tx.from == "system_rewards_pool" => {
                let node_id = tx.data.as_ref()
                    .and_then(|d| d.strip_prefix("reward_claim:"))
                    .and_then(|rest| rest.split(':').next())
                    .unwrap_or("");
                format!("claim_rewards:{}:{}", node_id, to_str)
            }
            
            // === NODEREGISTRATION ===
            // Two signing paths:
            // 1. SERVER-SIGNED (legacy): hybrid Ed25519 (ephemeral) + Dilithium3 (producer key)
            //    data field does NOT start with "client_node_reg:"
            //    Canonical: pipe-separated to match sign_node_registration_tx() in rpc.rs
            // 2. CLIENT-SIGNED (new flow): wallet Ed25519 key
            //    data field starts with "client_node_reg:" — set by handle_node_registration_client_submit
            //    Canonical: "client_node_reg:{node_id}:{wallet_address}:{registration_proof}:{timestamp}"
            qnet_state::TransactionType::NodeRegistration { node_id, wallet_address, registration_proof, .. } => {
                if tx.data.as_ref().map_or(false, |d| d.starts_with("client_node_reg:")) {
                    format!("client_node_reg:{}:{}:{}:{}",
                        node_id, wallet_address, registration_proof, tx.timestamp)
                } else {
                    // Legacy server-signed format
                    format!("{}|{}|{}|{}|{}|{}|{}",
                        tx.from, to_str, tx.amount, tx.nonce, tx.gas_price, tx.gas_limit, tx.timestamp)
                }
            }
            
            // === NODEACTIVATION (system TX, hybrid-signed by producer) ===
            qnet_state::TransactionType::NodeActivation { .. } => {
                format!("{}|{}|{}|{}|{}|{}|{}",
                    tx.from, to_str, tx.amount, tx.nonce, tx.gas_price, tx.gas_limit, tx.timestamp)
            }

            // === NODE-SIGNED SYSTEM TRANSACTIONS (signed with ephemeral Ed25519 + Dilithium) ===
            // HeartbeatCommitment, PingCommitmentWithSampling — use pipe-separated format
            // This matches node.rs:2817/2997 where nodes sign with:
            //   format!("{}|{}|{}|{}|{}|{}|{}", from, to, amount, nonce, gas_price, gas_limit, timestamp)
            _ => {
                format!("{}|{}|{}|{}|{}|{}|{}",
                    tx.from, to_str, tx.amount, tx.nonce, tx.gas_price, tx.gas_limit, tx.timestamp)
            }
        }
    }
    
    async fn verify_dilithium_tx_signature_async(tx: &qnet_state::Transaction) -> Result<bool, QNetError> {
        use crate::quantum_crypto::DilithiumSignature;
        
        let dilithium_sig = match &tx.dilithium_signature {
            Some(sig) if !sig.is_empty() => sig.clone(),
            _ => return Ok(true),
        };
        
        // v5.1: signer_id selection depends on TX type and signing path:
        //   1. Client-signed NodeRegistration (data starts with "client_node_reg:"):
        //      The mobile client embeds node_id (pseudonym like "light_mobile_XXXXXXXX") in the
        //      Dilithium signature format "dilithium_sig_{node_id}_{base64}". signer_id must be
        //      node_id, NOT dilithium_public_key (which is the raw hex key — a different format).
        //   2. All other TX: use dilithium_public_key as the node/signer identity for key lookup.
        let signer_id = match &tx.tx_type {
            qnet_state::TransactionType::NodeRegistration { node_id, .. }
                if tx.data.as_deref().unwrap_or("").starts_with("client_node_reg:") =>
            {
                node_id.clone()
            }
            _ => match &tx.dilithium_public_key {
                Some(pk) if !pk.is_empty() => pk.clone(),
                _ => return Err(QNetError::ValidationError(
                    "dilithium_public_key required when dilithium_signature is present".to_string()
                )),
            }
        };
        
        let timestamp = tx.timestamp;
        let message = Self::build_canonical_verify_message(tx);
        let sig_struct = DilithiumSignature {
            signature: dilithium_sig,
            algorithm: "CRYSTALS-Dilithium3".to_string(),
            timestamp,
            strength: "quantum-resistant".to_string(),
        };
        
        let handle = crate::unified_p2p::spawn_sigverify(async move {
            let crypto = match try_get_quantum_crypto() {
                Some(c) => c,
                None => return Err("Quantum crypto not initialized".to_string()),
            };
            
            match crypto.verify_dilithium_signature(&message, &sig_struct, &signer_id).await {
                Ok(valid) => Ok(valid),
                Err(e) => Err(format!("Dilithium error: {}", e)),
            }
        });
        
        match handle.await {
            Ok(Ok(r)) => Ok(r),
            Ok(Err(e)) => Err(QNetError::ValidationError(e)),
            Err(e) => Err(QNetError::ValidationError(format!("Runtime error: {}", e))),
        }
    }
    
