    /// PRODUCTION v2.19.25: Validate and add transaction received from P2P network
    /// Unlike submit_transaction(), this does NOT broadcast to avoid infinite loops
    pub async fn validate_and_add_network_transaction(&self, tx: qnet_state::Transaction) -> Result<String, QNetError> {
        // PRODUCTION VALIDATION - same as submit_transaction
        if let Err(validation_error) = tx.validate() {
            return Err(QNetError::ValidationError(format!("Transaction validation failed: {}", validation_error)));
        }
        
        // Signature validation with cryptographic verification
        // v2.53: System transactions don't need Ed25519 signature - validated through consensus
        // v2.81: HeartbeatCommitment validated through Dilithium signatures in samples + Merkle proofs
        let is_system_tx = matches!(tx.tx_type, 
            qnet_state::TransactionType::RewardDistribution | 
            qnet_state::TransactionType::PingCommitmentWithSampling { .. } |
            qnet_state::TransactionType::HeartbeatCommitment { .. } |
            qnet_state::TransactionType::LightNodeEligibilityBitmap { .. }
        );
        
        if is_system_tx {
            // System transactions validated through consensus and internal proofs
            // - RewardDistribution: validated through consensus
            // - PingCommitmentWithSampling: validated through Dilithium signatures + Merkle proofs + TX signature (v2.82)
            // - HeartbeatCommitment: validated through Dilithium signatures in samples + Merkle proofs + TX signature (v2.82)

            // SECURITY v6.1: system_emission RewardDistribution TXs are ONLY produced by
            // block producers and included directly in blocks. They must NEVER arrive via
            // P2P gossip — if they do, someone is trying to inject forged emission rewards.
            if matches!(tx.tx_type, qnet_state::TransactionType::RewardDistribution) && tx.from == "system_emission" {
                return Err(QNetError::ValidationError(
                    "system_emission RewardDistribution must not arrive via P2P gossip — block-level TX only".to_string()
                ));
            }

            if matches!(tx.tx_type, qnet_state::TransactionType::RewardDistribution) && tx.from != "system_emission" {
                // v3.35: FULL crypto verification for RewardDistribution (not just presence check!)
                // Prevents forged claim TXs from being injected via gossip
                let (sig, pubkey) = match (&tx.signature, &tx.public_key) {
                    (Some(s), Some(p)) if !s.is_empty() && !p.is_empty() => (s, p),
                    _ => return Err(QNetError::ValidationError(
                        "Reward claim must have Ed25519 signature and public_key".to_string()
                    )),
                };
                
                // CRITICAL v3.35: Verify Ed25519 signature on claim message
                // The message format is "claim_rewards:{node_id}:{wallet}" — same as RPC path
                // This ensures gossip path has same security level as direct RPC
                if !Self::verify_ed25519_tx_signature_async(&tx, sig, pubkey).await? {
                    return Err(QNetError::ValidationError(
                        "Invalid Ed25519 signature on reward claim TX (gossip)".to_string()
                    ));
                }
                
                // Validate data field format
                if tx.data.as_ref().map_or(true, |d| !d.starts_with("reward_claim:")) {
                    return Err(QNetError::ValidationError(
                        "Reward claim must have valid data field (reward_claim:...)".to_string()
                    ));
                }
                
                if is_info() { 
                    println!("[INFO][VERIFY] reward_claim_signature_verified_gossip to={}", 
                             tx.to.as_deref().unwrap_or("none")); 
                }
            }
            
            // PRODUCTION v2.85: MANDATORY hybrid signature verification for commitment TXs
            // L1 security requirement: Both Ed25519 AND Dilithium signatures MUST be present and valid
            if matches!(tx.tx_type, 
                qnet_state::TransactionType::HeartbeatCommitment { .. } | 
                qnet_state::TransactionType::PingCommitmentWithSampling { .. } |
                qnet_state::TransactionType::LightNodeEligibilityBitmap { .. }
            ) {
                // MANDATORY: Ed25519 signature REQUIRED
                let (sig, pubkey) = match (&tx.signature, &tx.public_key) {
                    (Some(s), Some(p)) if !s.is_empty() && !p.is_empty() => (s, p),
                    _ => return Err(QNetError::ValidationError(
                        "Commitment TX REQUIRES Ed25519 signature (hybrid security)".to_string()
                    )),
                };
                
                if !Self::verify_ed25519_tx_signature_async(&tx, sig, pubkey).await? {
                    return Err(QNetError::ValidationError("Invalid Ed25519 signature on commitment TX".to_string()));
                }
                
                // MANDATORY: Dilithium signature REQUIRED for post-quantum security
                if tx.dilithium_signature.as_ref().map_or(true, |s| s.is_empty()) {
                    return Err(QNetError::ValidationError(
                        "Commitment TX REQUIRES Dilithium signature (post-quantum security)".to_string()
                    ));
                }
                
                if !Self::verify_dilithium_tx_signature_async(&tx).await? {
                    return Err(QNetError::ValidationError("Invalid Dilithium signature on commitment TX".to_string()));
                }
                
                if is_info() {
                    println!("[INFO][VERIFY] commitment_tx_hybrid_verified type={:?}", 
                             std::mem::discriminant(&tx.tx_type));
                }
            }
        } else {
            // SECURITY v6.1: Ed25519 signature AND public_key are BOTH mandatory for user TXs.
            // Previously: if public_key was None, verification was silently skipped despite
            // signature being present — a TX with garbage signature + no public_key would pass.
            let sig = match tx.signature.as_ref().filter(|s| !s.is_empty()) {
                Some(s) => s,
                None => return Err(QNetError::ValidationError(
                    format!("Transaction signature is empty (type={:?})", std::mem::discriminant(&tx.tx_type))
                )),
            };
            let pubkey = match tx.public_key.as_ref().filter(|p| !p.is_empty()) {
                Some(p) => p,
                None => return Err(QNetError::ValidationError(
                    "Transaction has signature but public_key is missing — cannot verify Ed25519".to_string()
                )),
            };

            if !Self::verify_ed25519_tx_signature_async(&tx, sig, pubkey).await? {
                return Err(QNetError::ValidationError(format!(
                    "Invalid Ed25519 signature (type={:?})", std::mem::discriminant(&tx.tx_type)
                )));
            }

            if tx.dilithium_signature.is_some() {
                if !Self::verify_dilithium_tx_signature_async(&tx).await? {
                    return Err(QNetError::ValidationError("Invalid Dilithium signature".to_string()));
                }
            }
        }
        
        if tx.amount == 0 && matches!(tx.tx_type, qnet_state::TransactionType::Transfer { .. }) {
            return Err(QNetError::ValidationError("Transfer amount cannot be zero".to_string()));
        }
        
        // PROTOCOL: Commitment TXs skip standard account nonce (they use epoch-based semantics)
        // Deduplication is enforced at STATE level via committed_epochs (deterministic across all nodes)
        // NodeRegistration: no nonce semantics (one-time event, uniqueness enforced by
        // state-level registered_nodes DashMap populated from block history)
        let skip_nonce_check = matches!(tx.tx_type,
            qnet_state::TransactionType::HeartbeatCommitment { .. } |
            qnet_state::TransactionType::PingCommitmentWithSampling { .. } |
            qnet_state::TransactionType::LightNodeEligibilityBitmap { .. } |
            qnet_state::TransactionType::RewardDistribution { .. } |
            qnet_state::TransactionType::NodeRegistration { .. } |
            qnet_state::TransactionType::NodeActivation { .. }
        );
        
        // PROTOCOL: State-level dedup check for commitment TXs (prevents duplicate per node per epoch)
        if skip_nonce_check {
            let state = self.state.read().await;
            let epoch_interval: u64 = 14400;
            let is_duplicate = match &tx.tx_type {
                qnet_state::TransactionType::HeartbeatCommitment { node_id, window_start_height, .. } => {
                    state.is_epoch_committed("heartbeat", node_id, window_start_height / epoch_interval)
                }
                qnet_state::TransactionType::PingCommitmentWithSampling { window_start_height, .. } => {
                    state.is_epoch_committed("ping", &tx.from, window_start_height / epoch_interval)
                }
                qnet_state::TransactionType::LightNodeEligibilityBitmap { genesis_id, epoch, .. } => {
                    state.is_epoch_committed("bitmap", genesis_id, *epoch)
                }
                qnet_state::TransactionType::NodeRegistration { node_id, .. } => {
                    state.is_node_registered(node_id)
                }
                _ => false, // RewardDistribution / NodeActivation — no epoch dedup
            };
            if is_duplicate {
                return Err(QNetError::ValidationError(
                    format!("duplicate commitment TX: already committed for this epoch hash={}", &tx.hash[..16.min(tx.hash.len())])
                ));
            }
        }
        
        if !skip_nonce_check {
            let state = self.state.read().await;
            if let Some(account) = state.get_account(&tx.from) {
                let expected_nonce = account.nonce + 1;
                if tx.nonce != expected_nonce {
                    return Err(QNetError::ValidationError(format!(
                        "Invalid nonce: expected {}, got {}",
                        expected_nonce, tx.nonce
                    )));
                }
            } else if tx.nonce != 1 {
                return Err(QNetError::ValidationError("New account nonce must be 1".to_string()));
            }
        }
        
        // Balance validation for transfers
        if let qnet_state::TransactionType::Transfer { .. } = &tx.tx_type {
            let state = self.state.read().await;
            let balance = state.get_balance(&tx.from);
            // QUANTUM v2.25: Use effective_gas_price() for +50% Dilithium TX fee
            let total_cost = tx.amount + (tx.effective_gas_price() * tx.gas_limit);
            
            if balance < total_cost {
                return Err(QNetError::ValidationError(format!(
                    "Insufficient balance: {} < {} (need {} + gas)",
                    balance, total_cost, tx.amount
                )));
            }
        }
        
        let hash = hex::encode(&tx.hash);
        
        // Add to mempool (NO BROADCAST - already received from network)
        // v2.26: Direct access - SimpleMempool is already thread-safe
        // v2.77: Use SHA3-256 via calculate_hash() for NIST compliance
        let tx_hash = tx.calculate_hash();
        let tx_bytes = bincode::serialize(&tx).unwrap_or_default();
        
        if !self.mempool.add_binary_transaction(tx_bytes, tx_hash, tx.gas_price) {
                return Err(QNetError::ValidationError("Transaction already in mempool or mempool full".to_string()));
        }
        
        Ok(hash)
    }
    
    /// BENCHMARK: Submit transaction for load testing
    /// Skips balance validation for benchmark accounts (EON1benchmark*)
    /// Full signature validation and P2P broadcast still applied
    /// SECURITY: Requires QNET_BENCHMARK_MODE=true environment variable
    pub async fn submit_benchmark_transaction(&self, tx: qnet_state::Transaction) -> Result<String, QNetError> {
        use crate::benchmark::BenchmarkManager;
        
        // SECURITY v2.26: Only allow benchmark mode when explicitly enabled
        let benchmark_mode = std::env::var("QNET_BENCHMARK_MODE")
            .map(|v| v == "true" || v == "1")
            .unwrap_or(false);
        if !benchmark_mode {
            return Err(QNetError::ValidationError("Benchmark mode not enabled (set QNET_BENCHMARK_MODE=true)".to_string()));
        }
        
        // Only allow benchmark accounts
        if !BenchmarkManager::is_benchmark_account(&tx.from) {
            return Err(QNetError::ValidationError("Only benchmark accounts allowed".to_string()));
        }
        
        // Basic structure validation (skip balance check for benchmark)
        if let Err(validation_error) = tx.validate() {
            return Err(QNetError::ValidationError(format!("Transaction validation failed: {}", validation_error)));
        }
        
        // Signature validation
        if tx.signature.as_ref().map_or(true, |s| s.is_empty()) {
            return Err(QNetError::ValidationError("Transaction signature is empty".to_string()));
        }
        
        // Add to mempool - v2.26: Direct access - SimpleMempool is already thread-safe
        // v2.77: Use SHA3-256 via calculate_hash() for NIST compliance
        let tx_hash = tx.calculate_hash();
        let tx_bytes = bincode::serialize(&tx).unwrap_or_default();
        self.mempool.add_binary_transaction(tx_bytes.clone(), tx_hash.clone(), tx.gas_price);
        
        // PRODUCTION v2.26: Full P2P broadcast for realistic testing
        // With QNET_BENCHMARK_MODE=true, benchmark accounts have real balances in genesis
        // so TX are valid on ALL nodes → realistic distributed test
        if let Some(unified_p2p) = &self.unified_p2p {
            let _ = unified_p2p.broadcast_transaction(tx_bytes);
        }
        
        // PRODUCTION v2.26: Return SHA3(bincode) hash for consistency with mempool
        Ok(tx_hash)
    }
    
    /// BENCHMARK: Submit batch of transactions for high-throughput load testing
    /// REALISTIC: Full P2P broadcast - with QNET_BENCHMARK_MODE accounts have real balances in genesis
    /// Only difference from production: skip balance validation for benchmark accounts
    /// PRODUCTION v2.25: bincode serialization for 10-20x faster processing
    /// SECURITY: Requires QNET_BENCHMARK_MODE=true environment variable
    /// Returns number of successfully added transactions
    pub async fn submit_benchmark_batch(&self, transactions: Vec<qnet_state::Transaction>) -> Result<usize, QNetError> {
        use crate::benchmark::BenchmarkManager;
        
        // SECURITY v2.26: Only allow benchmark mode when explicitly enabled
        let benchmark_mode = std::env::var("QNET_BENCHMARK_MODE")
            .map(|v| v == "true" || v == "1")
            .unwrap_or(false);
        if !benchmark_mode {
            return Err(QNetError::ValidationError("Benchmark mode not enabled (set QNET_BENCHMARK_MODE=true)".to_string()));
        }
        
        if transactions.is_empty() {
            return Ok(0);
        }
        
        let mut confirmed = 0usize;
        // PRODUCTION v2.25: Store bincode bytes directly (no JSON overhead)
        let mut valid_txs: Vec<(Vec<u8>, String, u64)> = Vec::with_capacity(transactions.len());
        
        // PRODUCTION v2.26.6: FULL Ed25519 signature verification for honest benchmarks!
        // This ensures benchmark TPS reflects REAL cryptographic overhead
        let valid_sig_indices = Self::verify_ed25519_batch(&transactions);
        let valid_sig_set: std::collections::HashSet<usize> = valid_sig_indices.into_iter().collect();
        
        // Pre-validate and serialize all transactions with bincode
        for (idx, tx) in transactions.iter().enumerate() {
            // CRITICAL v2.26.6: Skip if signature verification failed
            if !valid_sig_set.contains(&idx) {
                continue;
            }
            
            // Only allow benchmark accounts
            if !BenchmarkManager::is_benchmark_account(&tx.from) {
                continue;
            }
            
            // Basic validation (skip balance check for benchmark)
            if tx.validate().is_err() {
                continue;
            }
            
            // PRODUCTION v2.25: bincode serialization (10-20x faster than JSON)
            // v2.77: Use SHA3-256 via calculate_hash() for NIST compliance
            if let Ok(tx_bytes) = bincode::serialize(&tx) {
                let tx_hash = tx.calculate_hash();
                valid_txs.push((tx_bytes, tx_hash, tx.gas_price));
                confirmed += 1;
            }
        }
        
        // v2.26: Direct access - SimpleMempool is already thread-safe (DashMap + parking_lot)
        // No external lock needed - eliminates 100K TPS bottleneck!
        if !valid_txs.is_empty() {
            let tx_data_for_broadcast: Vec<Vec<u8>> = valid_txs.iter()
                .map(|(tx_bytes, _, _)| tx_bytes.clone())
                .collect();
            
            // Use trusted batch add - 10-50x faster than individual adds
            let actually_added = self.mempool.add_binary_transaction_batch_trusted(valid_txs);
            confirmed = actually_added;
            
            // PRODUCTION v2.25: Use batch broadcast for high-throughput
            // Single QUIC message for entire batch - reduces stream overhead
        if let Some(unified_p2p) = &self.unified_p2p {
                if !tx_data_for_broadcast.is_empty() {
                    let _ = unified_p2p.broadcast_transaction_batch(tx_data_for_broadcast);
                }
            }
        }
        
        Ok(confirmed)
    }
    
    pub async fn get_mempool_transactions(&self) -> Vec<qnet_state::Transaction> {
        // v2.26: Direct access - SimpleMempool is already thread-safe
        let tx_bytes_list = self.mempool.get_pending_binary_transactions(1000);
        
        // Deserialize with bincode (10-20x faster than JSON)
        let mut transactions = Vec::new();
        for tx_bytes in tx_bytes_list {
            // Try bincode first (new format), fallback to JSON (legacy)
            if let Ok(tx) = bincode::deserialize::<qnet_state::Transaction>(&tx_bytes) {
                transactions.push(tx);
            } else if let Ok(tx_json) = String::from_utf8(tx_bytes) {
                // Legacy JSON fallback for backward compatibility
            if let Ok(tx) = serde_json::from_str::<qnet_state::Transaction>(&tx_json) {
                transactions.push(tx);
                }
            }
        }
        transactions
    }
    
    pub async fn add_transaction_to_mempool(&self, tx: qnet_state::Transaction) -> Result<String, QNetError> {
        self.submit_transaction(tx).await
    }
    
    pub async fn get_account(&self, address: &str) -> Result<Option<qnet_state::Account>, QNetError> {
        let state = self.state.read().await;
        Ok(state.get_account(address))
    }
    
    pub async fn get_balance(&self, address: &str) -> Result<u64, QNetError> {
        let state = self.state.read().await;
        Ok(state.get_balance(address))
    }
    
    /// v3.11: Get balance with Merkle proof for Light client trustless verification
    /// 
    /// Returns BalanceProof that includes:
    /// - Balance and nonce
    /// - Merkle proof path
    /// - State root and block height
    /// 
    /// Light clients can verify proof against state_root without trusting the API
    pub async fn get_balance_with_proof(&self, address: &str) -> Result<qnet_state::BalanceProof, QNetError> {
        let state = self.state.read().await;
        state.get_balance_with_proof(address)
            .ok_or_else(|| QNetError::StateError(format!("Account not found: {}", address)))
    }
    
    pub async fn get_stats(&self) -> Result<serde_json::Value, QNetError> {
        let height = self.get_height().await;
        let peer_count = self.get_peer_count().await?;
        let mempool_size = self.get_mempool_size().await?;
        let regional_health = self.get_regional_health();
        
        Ok(serde_json::json!({
            "height": height,
            "peers": peer_count,
            "mempool_size": mempool_size,
            "regional_health": regional_health,
            "node_type": format!("{:?}", self.node_type),
            "region": format!("{:?}", self.region),
            "node_id": self.node_id,
            "sharding_enabled": self.perf_config.enable_sharding,
            "parallel_validation": self.perf_config.parallel_validation,
        }))
    }
    
    /// Start sync process after node restart or new node join
    pub async fn start_sync_if_needed(&self) -> Result<(), QNetError> {
        // CRITICAL: Mark node as syncing to prevent consensus participation
        if is_info() { println!("[INFO][SYNC] sync_check_start"); }
        
        // Set a flag that we're syncing (prevents producing blocks)
        let _is_syncing = Arc::new(std::sync::atomic::AtomicBool::new(true));
        
        // PRODUCTION: Try to load from snapshot first for fast sync
        if let Ok(latest_snapshot) = self.storage.get_latest_snapshot_height() {
            if let Some(snapshot_height) = latest_snapshot {
                let current_height = self.get_height().await;
                
                // If we're far behind and have a snapshot, use it
                if current_height < snapshot_height.saturating_sub(1000) {
                    println!("[SYNC] 📸 Found snapshot at height {}, loading for fast sync...", snapshot_height);
                    
                    if let Err(e) = self.storage.load_state_snapshot(snapshot_height).await {
                        println!("[WARN][SYNC] Failed to load snapshot: {}, falling back to normal sync", e);
                    } else {
                        // Update our height to snapshot height
                        *self.height.write().await = snapshot_height;
                        if is_info() { println!("[INFO][SYNC] snapshot_loaded h={}", snapshot_height); }
                        
                        // Continue syncing from snapshot height
                        if let Some(ref p2p) = self.unified_p2p {
                            if let Some(network_height) = p2p.get_cached_network_height() {
                                if network_height > snapshot_height {
                                    println!("[SYNC] 📥 Syncing remaining blocks {}-{}", snapshot_height + 1, network_height);
                                    return self.sync_blocks(snapshot_height + 1, network_height).await;
                                }
                            }
                        }
                        return Ok(());
                    }
                }
            }
        }
        
        // Check if we have pending sync from previous run
        if let Ok(Some((_from, to, current))) = self.storage.load_sync_progress() {
            if is_info() { println!("[INFO][SYNC] resume from={} to={}", current, to); }
            
            if let Some(ref p2p) = self.unified_p2p {
                // Continue sync from where we left off
                if let Err(e) = p2p.batch_sync(current, to, 100).await {
                    return Err(QNetError::SyncError(format!("Sync failed: {}", e)));
                }
                
                // Clear sync progress after successful completion
                self.storage.clear_sync_progress()?;
                if is_info() { println!("[INFO][SYNC] sync_ok"); }
            }
        } else {
            // Check if we're behind the network
            if let Some(ref p2p) = self.unified_p2p {
                let peers = p2p.get_validated_active_peers();
                if !peers.is_empty() {
                    let current_height = self.get_height().await;
                    
                    // CRITICAL FIX: Query network height from peers
                    let network_height = self.query_network_height().await?;
                    
                    if is_debug() { println!("[DBG][SYNC] local={} net={}", current_height, network_height); }
                    
                    // If we're behind, start sync
                    if network_height > current_height + 10 { // Allow 10 block tolerance
                        println!("[WARN][SYNC] Node is {} blocks behind, starting sync...", 
                                 network_height - current_height);
                        
                        // Light nodes are thin clients - they don't sync blocks
                        // They get all data (balance, TX history) via RPC from Full/Super nodes
                        if self.node_type == NodeType::Light {
                            if is_info() { println!("[INFO][SYNC] light_node_skip reason=thin_client"); }
                        } else {
                            // Full/Super nodes sync complete history
                            // For new nodes (height 0 or 1), start from block 1 (first microblock)
                            let sync_from = if current_height <= 1 { 1 } else { current_height + 1 };
                            
                            // Sync to network height
                            self.sync_blocks(sync_from, network_height).await?;
                            
                            // PRODUCTION v2.19.12: Sync macroblocks for Full/Super nodes
                            // Macroblocks contain consensus data and state roots
                            let local_macro_index = current_height / 90;
                            let network_macro_index = network_height / 90;
                            if network_macro_index > local_macro_index {
                                if is_info() {
                                    println!("[INFO][MACROBLOCK-SYNC] syncing_macroblocks from={} to={}", 
                                             local_macro_index + 1, network_macro_index);
                                }
                                self.sync_macroblocks(local_macro_index + 1, network_macro_index).await?;
                            }
                        }
                    } else {
                        if is_info() { println!("[INFO][SYNC] up_to_date"); }
                    }
                } else {
                    println!("[WARN][SYNC] No peers available for sync check");
                }
            }
        }
        
        Ok(())
    }
    
    /// Sync blocks from network
    pub async fn sync_blocks(&self, from_height: u64, to_height: u64) -> Result<(), QNetError> {
        if let Some(ref p2p) = self.unified_p2p {
            // Start sync process
            if is_info() { println!("[INFO][SYNC] block_sync {}-{}", from_height, to_height); }
            
            // Save sync progress for recovery
            self.storage.save_sync_progress(from_height, to_height, from_height)?;
            
            // Use batch sync for efficiency
            if let Err(e) = p2p.batch_sync(from_height, to_height, 100).await {
                return Err(QNetError::SyncError(format!("Batch sync failed: {}", e)));
            }
            
            // Clear sync progress after success
            self.storage.clear_sync_progress()?;
            if is_info() { println!("[INFO][SYNC] sync_complete"); }
            
            Ok(())
        } else {
            Err(QNetError::NetworkError("P2P network not initialized".to_string()))
        }
    }
    
    /// Handle incoming sync request from peer
    /// CRITICAL FIX v2.61: Size-based batched sync to prevent QUIC message loss
    pub async fn handle_sync_request(&self, from_height: u64, to_height: u64, requester_id: String) -> Result<(), QNetError> {
        if is_info() { 
            println!("[INFO][SYNC] request from={} heights={}-{}", requester_id, from_height, to_height); 
        }
        
        // Get microblocks from storage (already in network format)
        let blocks_data = self.storage.get_microblocks_range(from_height, to_height).await?;
        
        if is_trace() { 
            println!("[TRC][SYNC] get_range({}, {}) blocks={}", from_height, to_height, blocks_data.len()); 
        }
        
        if blocks_data.is_empty() {
            if is_debug() { println!("[DBG][SYNC] empty_response heights={}-{}", from_height, to_height); }
            return Ok(());
        }
        
        if let Some(ref p2p) = self.unified_p2p {
            // ═══════════════════════════════════════════════════════════════════════════
            // CRITICAL FIX v2.61: SIZE-BASED BATCHING for intercontinental reliability
            // ═══════════════════════════════════════════════════════════════════════════
            // Problem: Sending large messages via QUIC = fragmentation = packet loss = failure
            // Root cause: 101 blocks with 50K TX each = ~10MB, any UDP packet loss = "Message too short"
            // Solution: Batch by SIZE (not count) - max 1MB per message (safe for QUIC/UDP)
            // 
            // Why SIZE matters more than COUNT:
            // - Empty block: ~20KB
            // - Block with 50K TX: ~12MB!
            // - 10 empty blocks: 200KB (OK)
            // - 1 block with 50K TX: 12MB (FAIL)
            // ═══════════════════════════════════════════════════════════════════════════
            const MAX_BATCH_SIZE_BYTES: usize = 1_000_000;  // 1MB max per QUIC message
            const SYNC_BATCH_DELAY_MS: u64 = 5;  // 5ms pacing between batches
            
            // Find peer address
            let peer_addr = p2p.get_peer_address_by_id(&requester_id)
                .or_else(|| {
                    let peers = p2p.get_validated_active_peers();
                    peers.iter().find(|p| p.id == requester_id).map(|p| p.addr.clone())
                });
            
            let Some(addr) = peer_addr else {
                if is_info() { println!("[WARN][SYNC] peer_not_found id={}", requester_id); }
                return Ok(());
            };
            
            // ═══════════════════════════════════════════════════════════════════════════
            // CRITICAL FIX v2.61: Large blocks (>1MB) use ShredProtocol for reliability
            // Small blocks use batched BlocksBatch messages
            // blocks_data is Vec<(u64, Vec<u8>)> - already (height, data) pairs
            // ═══════════════════════════════════════════════════════════════════════════
            const SHRED_THRESHOLD_BYTES: usize = 1_000_000;  // Blocks >1MB use ShredProtocol
            
            // Separate large blocks (ShredProtocol) from small blocks (BatchSync)
            let mut large_blocks: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut small_blocks: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut total_size: usize = 0;
            
            for (height, block_data) in &blocks_data {
                let block_size = block_data.len();
                total_size += block_size;
                
                if block_size > SHRED_THRESHOLD_BYTES {
                    large_blocks.push((*height, block_data.clone()));
                } else {
                    small_blocks.push((*height, block_data.clone()));
                }
            }
            
            // Send large blocks via ShredProtocol (reliable for 20MB+)
            if !large_blocks.is_empty() {
                if is_info() {
                    println!("[INFO][SYNC] sending {} large blocks via ShredProtocol to={}", 
                             large_blocks.len(), requester_id);
                }
                for (height, block_data) in large_blocks {
                    p2p.send_block_via_shred_to_peer(&addr, height, block_data, false).await;
                }
            }
            
            // Build size-based batches for small blocks
            // BlocksBatch.blocks is Vec<(u64, Vec<u8>)> - (height, data) pairs
            let mut batches: Vec<Vec<(u64, Vec<u8>)>> = Vec::new();
            let mut batch_heights: Vec<(u64, u64)> = Vec::new();  // (from, to) for each batch
            let mut current_batch: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut current_batch_size: usize = 0;
            let mut batch_start_height: Option<u64> = None;
            let mut last_height: u64 = 0;
            
            for (height, block) in &small_blocks {
                let block_size = block.len();
                
                // If adding this block exceeds limit, start new batch
                if current_batch_size + block_size > MAX_BATCH_SIZE_BYTES && !current_batch.is_empty() {
                    batches.push(current_batch);
                    batch_heights.push((batch_start_height.unwrap_or(*height), last_height));
                    current_batch = Vec::new();
                    current_batch_size = 0;
                    batch_start_height = None;
                }
                
                if batch_start_height.is_none() {
                    batch_start_height = Some(*height);
                }
                last_height = *height;
                
                current_batch.push((*height, block.clone()));
                current_batch_size += block_size;
            }
            
            // Don't forget last batch
            if !current_batch.is_empty() {
                batches.push(current_batch);
                batch_heights.push((batch_start_height.unwrap_or(from_height), last_height));
            }
            
            let num_batches = batches.len();
            let total_blocks = blocks_data.len();
            let small_blocks_count = small_blocks.len();
            let large_blocks_count = total_blocks - small_blocks_count;
            
            if is_info() { 
                println!("[INFO][SYNC] sending blocks={} (small={} large={}) size={}KB batches={} to={}", 
                         total_blocks, small_blocks_count, large_blocks_count, 
                         total_size / 1024, num_batches, requester_id); 
            }
            
            // Send small blocks batches with pacing
            for (batch_idx, batch) in batches.iter().enumerate() {
                let (batch_from, batch_to) = batch_heights.get(batch_idx)
                    .copied()
                    .unwrap_or((from_height, from_height));
                
                let response = NetworkMessage::BlocksBatch {
                    blocks: batch.clone(),
                    from_height: batch_from,
                    to_height: batch_to,
                    sender_id: self.node_id.clone(),
                };
                
                p2p.send_network_message(&addr, response);
                
                if is_debug() { 
                    let batch_size: usize = batch.iter().map(|(_, b)| b.len()).sum();
                    println!("[DBG][SYNC] batch={}/{} heights={}-{} size={}KB", 
                             batch_idx + 1, num_batches, batch_from, batch_to, batch_size / 1024); 
                }
                
                // Pacing delay between batches (except last)
                if batch_idx < num_batches - 1 {
                    tokio::time::sleep(std::time::Duration::from_millis(SYNC_BATCH_DELAY_MS)).await;
                }
            }
            
            if is_info() { 
                println!("[INFO][SYNC] sent blocks={} (shred={} batch={}) to={}", 
                         total_blocks, large_blocks_count, small_blocks_count, requester_id); 
            }
        }
        
        Ok(())
    }
    
    // =========================================================================
    // MACROBLOCK SYNC METHODS (PRODUCTION v2.19.12)
    // =========================================================================
    
    /// Handle incoming macroblock sync request from peer
    /// PRODUCTION: Full macroblock sync support for new nodes joining network
    /// CRITICAL FIX v2.61: Size-based batched sync to prevent QUIC message loss
    pub async fn handle_macroblock_sync_request(&self, from_index: u64, to_index: u64, requester_id: String) -> Result<(), QNetError> {
        if is_info() { 
            println!("[INFO][MB-SYNC] request from={} indices={}-{}", requester_id, from_index, to_index); 
        }
        
        // Get macroblocks from storage
        let macroblocks_data = self.storage.get_macroblocks_range(from_index, to_index).await?;
        
        if is_trace() { 
            println!("[TRC][MB-SYNC] get_range({}, {}) macroblocks={}", from_index, to_index, macroblocks_data.len()); 
        }
        
        if macroblocks_data.is_empty() {
            if is_debug() { println!("[DBG][MB-SYNC] empty_response indices={}-{}", from_index, to_index); }
            return Ok(());
        }
        
        if let Some(ref p2p) = self.unified_p2p {
            // ═══════════════════════════════════════════════════════════════════════════
            // CRITICAL FIX v2.61: SIZE-BASED BATCHING for macroblocks
            // Macroblocks are typically larger, use conservative limit
            // ═══════════════════════════════════════════════════════════════════════════
            const MAX_BATCH_SIZE_BYTES: usize = 500_000;  // 500KB max per message (macroblocks are bigger)
            const MB_SYNC_BATCH_DELAY_MS: u64 = 10;  // 10ms pacing between batches
            
            // Find peer address
            let peer_addr = p2p.get_peer_address_by_id(&requester_id)
                .or_else(|| {
                    let peers = p2p.get_validated_active_peers();
                    peers.iter().find(|p| p.id == requester_id).map(|p| p.addr.clone())
                });
            
            let Some(addr) = peer_addr else {
                if is_info() { println!("[WARN][MB-SYNC] peer_not_found id={}", requester_id); }
                return Ok(());
            };
            
            // Build size-based batches
            // macroblocks_data is already Vec<(u64, Vec<u8>)> - (index, data) pairs
            let mut batches: Vec<Vec<(u64, Vec<u8>)>> = Vec::new();
            let mut current_batch: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut current_batch_size: usize = 0;
            let mut total_size: usize = 0;
            
            for (mb_index, mb_data) in &macroblocks_data {
                let mb_size = mb_data.len();
                total_size += mb_size;
                
                // If single macroblock exceeds limit, send it alone
                if mb_size > MAX_BATCH_SIZE_BYTES {
                    if !current_batch.is_empty() {
                        batches.push(current_batch);
                        current_batch = Vec::new();
                        current_batch_size = 0;
                    }
                    batches.push(vec![(*mb_index, mb_data.clone())]);
                    continue;
                }
                
                // If adding this macroblock exceeds limit, start new batch
                if current_batch_size + mb_size > MAX_BATCH_SIZE_BYTES && !current_batch.is_empty() {
                    batches.push(current_batch);
                    current_batch = Vec::new();
                    current_batch_size = 0;
                }
                
                current_batch.push((*mb_index, mb_data.clone()));
                current_batch_size += mb_size;
            }
            
            if !current_batch.is_empty() {
                batches.push(current_batch);
            }
            
            let num_batches = batches.len();
            let total_macroblocks = macroblocks_data.len();
            
            if is_info() { 
                println!("[INFO][MB-SYNC] sending macroblocks={} size={}KB batches={} to={}", 
                         total_macroblocks, total_size / 1024, num_batches, requester_id); 
            }
            
            // Send batches with pacing
            for (batch_idx, batch) in batches.iter().enumerate() {
                // Get from/to from actual batch content
                let batch_from = batch.first().map(|(idx, _)| *idx).unwrap_or(from_index);
                let batch_to = batch.last().map(|(idx, _)| *idx).unwrap_or(batch_from);
                
                let response = NetworkMessage::MacroblocksBatch {
                    macroblocks: batch.clone(),
                    from_index: batch_from,
                    to_index: batch_to,
                    sender_id: self.node_id.clone(),
                };
                
                p2p.send_network_message(&addr, response);
                
                if is_debug() { 
                    let batch_size: usize = batch.iter().map(|(_, b)| b.len()).sum();
                    println!("[DBG][MB-SYNC] batch={}/{} indices={}-{} size={}KB", 
                             batch_idx + 1, num_batches, batch_from, batch_to, batch_size / 1024); 
                }
                
                if batch_idx < num_batches - 1 {
                    tokio::time::sleep(std::time::Duration::from_millis(MB_SYNC_BATCH_DELAY_MS)).await;
                }
            }
            
            if is_info() { 
                println!("[INFO][MB-SYNC] sent macroblocks={} batches={} to={}", total_macroblocks, num_batches, requester_id); 
            }
        }
        
        Ok(())
    }
    
    /// Process received macroblock from network sync
    /// PRODUCTION: Validates and saves macroblock to storage
    pub async fn process_received_macroblock(&self, received: crate::unified_p2p::ReceivedBlock) -> Result<(), QNetError> {
        let index = received.height;  // For macroblocks, height = index
        
        println!("[MACROBLOCK-SYNC] 📦 Processing received macroblock #{} from {}", 
                 index, received.from_peer);
        
        // Decompress if needed
        let data = if received.data.len() >= 4 && received.data[0..4] == [0x28, 0xb5, 0x2f, 0xfd] {
            zstd::decode_all(&received.data[..])
                .map_err(|e| QNetError::StorageError(format!("Decompression failed: {}", e)))?
        } else {
            received.data.clone()
        };
        
        // Deserialize and validate macroblock
        let macroblock: qnet_state::MacroBlock = bincode::deserialize(&data)
            .map_err(|e| QNetError::ValidationError(format!("Invalid macroblock format: {}", e)))?;
        
        // Basic validation
        if macroblock.height != index {
            return Err(QNetError::ValidationError(format!(
                "Macroblock height mismatch: expected {}, got {}", index, macroblock.height
            )));
        }
        
        // v3.00: Check if macroblock already saved (e.g., by BFT participant during consensus)
        // CRITICAL: Do NOT return early — emission rewards still need processing!
        // process_macroblock_heartbeats_deterministic has built-in dedup via processed_set
        let already_saved = self.storage.get_macroblock_by_height(index)
            .map(|mb| mb.is_some())
            .unwrap_or(false);
        
        if already_saved {
            // BFT participants save macroblock during consensus, broadcast arrives later
            // Skip save + validation, but continue to emission reward processing below
            if is_info() {
                println!("[INFO][MB-SYNC] already_saved mb={} skip_save process_rewards", index);
            }
            crate::unified_p2p::clear_macroblock_pending_sync(index);
        } else {
            // New macroblock — validate, save, apply reputation
            
            // Validate microblock hashes exist (if we have the microblocks)
            let expected_start = if index == 1 { 1 } else { (index - 1) * 90 + 1 };
            let expected_end = index * 90;
            
            let mut missing_microblocks = Vec::new();
            for height in expected_start..=expected_end {
                if self.storage.load_microblock(height)?.is_none() {
                    missing_microblocks.push(height);
                }
            }
            
            if !missing_microblocks.is_empty() {
                println!("[WARN][MB-SYNC] Macroblock #{} references {} missing microblocks (first: {})", 
                         index, missing_microblocks.len(), missing_microblocks[0]);
            }
            
            // Save macroblock to storage
            self.storage.save_macroblock(index, &macroblock).await?;
            
            // v3.1: Clear from pending sync tracker after successful save
            crate::unified_p2p::clear_macroblock_pending_sync(index);
            
            // v2.48 FIX: Update global finalized round after successful save
            let round = index * 90;
            let prev_round = LAST_FINALIZED_CONSENSUS_ROUND.load(std::sync::atomic::Ordering::SeqCst);
            if round > prev_round {
                LAST_FINALIZED_CONSENSUS_ROUND.store(round, std::sync::atomic::Ordering::SeqCst);
                LAST_FINALIZED_HEIGHT.store(round, std::sync::atomic::Ordering::SeqCst);
                println!("[INFO][MB-SYNC] finalized_round_updated mb={} round={} finality_h={}", index, round, round);
            }
            
            // v2.24: Apply reputation snapshot from macroblock
            if let Some(ref snapshot_data) = macroblock.consensus_data.reputation_snapshot {
                if !snapshot_data.is_empty() {
                    if let Some(ref p2p) = self.unified_p2p {
                        if let Some(rep_arc) = p2p.get_deterministic_reputation() {
                            let mut rep_state = rep_arc.write();
                            match rep_state.apply_snapshot(snapshot_data) {
                                Ok(count) => {
                                    if is_info() {
                                        println!("[INFO][MB-SYNC] snapshot_applied nodes={}", count);
                                    }
                                }
                                Err(e) => {
                                    if is_warn() {
                                        println!("[WARN][MB-SYNC] snapshot_failed err={}", e);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        
        // ═══════════════════════════════════════════════════════════════════════════
        // v2.41.0: Apply heartbeat summaries from macroblock for deterministic rewards
        // CRITICAL: Only process at EMISSION MacroBlocks (every 160 macroblocks = 4 hours)
        // Heartbeats are recorded in each MacroBlock for sync, but rewards calculated only at emission
        // 
        // Math: 14400 microblocks / 90 blocks per macroblock = 160 macroblocks per 4h window
        // Emission MacroBlocks: 160, 320, 480, 640... (index % 160 == 0)
        // ═══════════════════════════════════════════════════════════════════════════
        const EMISSION_MACROBLOCK_INTERVAL: u64 = 160; // 14400 / 90 = 160 macroblocks per 4h
        let is_emission_macroblock = index > 0 && index % EMISSION_MACROBLOCK_INTERVAL == 0;
        
        if is_emission_macroblock {
            // v2.99: ALL nodes process rewards from MacroBlock (deterministic!)
            // MacroBlock contains reward_heartbeats → ALL nodes use SAME data → SAME result!
            if let Some(ref heartbeats_data) = macroblock.consensus_data.reward_heartbeats {
                if !heartbeats_data.is_empty() {
                    if let Ok(heartbeat_summaries) = bincode::deserialize::<Vec<qnet_state::HeartbeatSummary>>(heartbeats_data) {
                        // PRODUCTION v2.78: Merge Full/Super nodes with Light nodes for unified processing
                        let mut all_summaries = heartbeat_summaries.clone();
                        
                        // Extract Light node rewards from MacroBlock
                        if let Some(ref light_data) = macroblock.consensus_data.reward_light_nodes {
                            if let Ok(light_node_rewards) = bincode::deserialize::<std::collections::HashMap<String, u32>>(light_data) {
                                // Convert Light nodes to HeartbeatSummary format
                                for (light_node_id, _ping_count) in &light_node_rewards {
                                    all_summaries.push(qnet_state::HeartbeatSummary {
                                        node_id: light_node_id.clone(),
                                        node_type: 0, // Light
                                        heartbeat_count: 1, // 1 ping per epoch
                                        first_heartbeat: 0,
                                        last_heartbeat: 0,
                                        is_eligible: true, // Already validated by PingCommitment
                                    });
                                }
                            }
                        }
                        
                        // Convert ALL nodes (Light/Full/Super) to HeartbeatSummaryData
                        let summary_data: Vec<qnet_consensus::HeartbeatSummaryData> = all_summaries.iter()
                            .map(|s| qnet_consensus::HeartbeatSummaryData {
                                node_id: s.node_id.clone(),
                                node_type: s.node_type,
                                heartbeat_count: s.heartbeat_count,
                                first_heartbeat: s.first_heartbeat,
                                last_heartbeat: s.last_heartbeat,
                                is_eligible: s.is_eligible,
                            })
                            .collect();
                        
                        let reward_manager_arc = self.get_reward_manager();
                        let mut reward_mgr = reward_manager_arc.write().await;
                        let pool2_total = macroblock.consensus_data.pool2_total_fees;
                        let pool3_total = macroblock.consensus_data.pool3_total_activations;
                        
                        match reward_mgr.process_macroblock_heartbeats_deterministic(
                            index,
                            &summary_data,
                            pool2_total,
                            pool3_total,
                        ) {
                            Ok(was_processed) => {
                                if was_processed {
                                    let eligible = heartbeat_summaries.iter().filter(|s| s.is_eligible).count();
                                    if is_info() {
                                        println!("[INFO][REWARDS] SYNC rewards_calculated mb={} nodes={} eligible={}", 
                                                 index, heartbeat_summaries.len(), eligible);
                                    }
                                    
                                    // Update total_supply
                                    let total_emission = reward_mgr.get_last_epoch_emission();
                                    drop(reward_mgr);
                                    
                                    if total_emission > 0 {
                                        let state = self.state.read().await;
                                        if let Err(e) = (*state).emit_rewards(total_emission) {
                                            eprintln!("[ERR][REWARDS] supply_update_fail err={}", e);
                                        } else {
                                            let new_supply = (*state).get_total_supply();
                                            if is_info() {
                                                println!("[INFO][REWARDS] SYNC supply_updated emission={} total={} QNC", 
                                                         total_emission / 1_000_000_000, new_supply / 1_000_000_000);
                                            }
                                        }
                                        drop(state);
                                    }
                                    
                                    // v7.0: update_pending_rewards REMOVED — now applied via emission TX in block execution
                                    // Persist pending rewards to RocksDB (survive restarts)
                                    let reward_manager_arc = self.get_reward_manager();
                                    let mut updated_count = 0;
                                    {
                                        let reward_mgr_rd = reward_manager_arc.read().await;
                                        let accrual_node_ids: Vec<String> = reward_mgr_rd.get_last_epoch_accruals().keys().cloned().collect();
                                        for node_id in &accrual_node_ids {
                                            if let Some(reward) = reward_mgr_rd.get_pending_reward(node_id) {
                                                if let Err(e) = self.storage.save_pending_reward(node_id, reward) {
                                                    eprintln!("[WARN][REWARDS] pending_save_fail node={} err={}", node_id, e);
                                                } else {
                                                    updated_count += 1;
                                                }
                                            }
                                        }
                                    }
                                    
                                    if is_info() && updated_count > 0 {
                                        println!("[INFO][REWARDS] SYNC pending_persisted count={}", updated_count);
                                    }
                                    
                                    // v3.00: Fully async snapshot — DashMap iterate + serialize in spawn_blocking
                                    // SCALABILITY: At 1M+ accounts — Tokio blocked for 0ms
                                    let state = self.state.read().await;
                                    let state_root = (*state).calculate_state_root().unwrap_or([0u8; 32]);
                                    let accounts_arc = (*state).accounts.clone(); // Arc bump — O(1)
                                    drop(state);
                                    
                                    if accounts_arc.len() > 0 {
                                        let storage_bg = self.storage.clone();
                                        let snap_index = index;
                                        tokio::spawn(async move {
                                            let state_data = match tokio::task::spawn_blocking(move || {
                                                let accounts: Vec<(String, qnet_state::Account)> = accounts_arc.iter()
                                                    .map(|e| (e.key().clone(), e.value().clone()))
                                                    .collect();
                                                bincode::serialize(&accounts)
                                            }).await {
                                                Ok(Ok(data)) => data,
                                                Ok(Err(e)) => {
                                                    eprintln!("[ERR][REWARDS] bg_serialize_fail mb={} err={}", snap_index, e);
                                                    return;
                                                }
                                                Err(e) => {
                                                    eprintln!("[ERR][REWARDS] bg_spawn_fail mb={} err={}", snap_index, e);
                                                    return;
                                                }
                                            };
                                            
                                            if !state_data.is_empty() {
                                                if let Err(e) = storage_bg.save_state_snapshot(snap_index, state_root, state_data.clone()).await {
                                                    eprintln!("[ERR][REWARDS] bg_snapshot_fail mb={} err={}", snap_index, e);
                                                } else {
                                                    println!("[INFO][REWARDS] SYNC bg_snapshot_saved mb={} size={}KB", snap_index, state_data.len() / 1024);
                                                }
                                            }
                                        });
                                    }
                                    
                                    // Mark as processed
                                    let reward_manager_arc = self.get_reward_manager();
                                    let mut reward_mgr = reward_manager_arc.write().await;
                                    let mut processed_set = reward_mgr.get_processed_emission_macroblocks().clone();
                                    processed_set.insert(index);
                                    reward_mgr.set_processed_emission_macroblocks(processed_set.clone());
                                    drop(reward_mgr);
                                    
                                    if let Err(e) = self.storage.save_processed_emission_macroblocks(&processed_set) {
                                        eprintln!("[WARN][REWARDS] processed_save_fail mb={} err={}", index, e);
                                    }
                                } else {
                                    if is_warn() {
                                        println!("[WARN][REWARDS] SYNC already_processed mb={}", index);
                                    }
                                }
                            }
                            Err(e) => {
                                eprintln!("[ERR][REWARDS] SYNC process_fail mb={} err={}", index, e);
                            }
                        }
                    }
                }
            }
        }
        
        if is_info() && !already_saved { 
            println!("[INFO][MB-SYNC] saved mb={} microblocks={}", index, macroblock.micro_blocks.len()); 
        }
        
        Ok(())
    }
    
    /// Sync macroblocks from network
    /// PRODUCTION: Requests macroblocks from peers and waits for response
    pub async fn sync_macroblocks(&self, from_index: u64, to_index: u64) -> Result<(), QNetError> {
        if let Some(ref p2p) = self.unified_p2p {
            println!("[MACROBLOCK-SYNC] 🔄 Starting macroblock sync from {} to {}", from_index, to_index);
            
            // Use batch sync for efficiency (max 10 macroblocks per request)
            let mut current = from_index;
            while current <= to_index {
                let batch_end = std::cmp::min(current + 9, to_index);
                
                if let Err(e) = p2p.sync_macroblocks(current, batch_end).await {
                    println!("[MACROBLOCK-SYNC] ⚠️ Failed to request macroblocks {}-{}: {}", current, batch_end, e);
                    // Continue with next batch instead of failing completely
                }
                
                current = batch_end + 1;
                
                // Small delay between batches to avoid overwhelming peers
                tokio::time::sleep(Duration::from_millis(200)).await;
            }
            
            println!("[MACROBLOCK-SYNC] ✅ Macroblock sync requests sent!");
            Ok(())
        } else {
            Err(QNetError::NetworkError("P2P system not available".to_string()))
        }
    }
    
